        if e.cost and not e.product and not e.special and w == M.world() then
            if pick == e.name then return i, e end
            if pick == "Best I Can Buy" and wins >= e.cost then best = i end
        end
    end
    if best then return best, D.eggs[best] end
end
function F.syncAutoDel()
    local sel = val("p_del", {}) or {}
    for i = 1, 4 do
        local want = sel[RARITY[i]] == true
        local has = F.autoDel["r" .. i] == true
        if has ~= want then
            M.fire("PetAction", "autodel", i)
            F.autoDel["r" .. i] = want
            task.wait(0.3)
        end
    end
end
function F.petMult(p)
    if D.PL and D.PL.mult then
        local ok, m = pcall(D.PL.mult, p)
        if ok and tonumber(m) then return tonumber(m) end
    end
    local e = D.eggs[p.e]
    local base = e and e.pets and e.pets[p.p] and tonumber(e.pets[p.p].mult) or 1
    return base * ((p.t or 0) + 1)
end
function F.freeSpace(all)
    local st = F.pets
    if type(st) ~= "table" or type(st.pets) ~= "table" then return 0 end
    local eq = {}
    for _, u in pairs(st.equipped or {}) do eq[u] = true end
    local floor = math.huge
    for _, p in ipairs(st.pets) do if eq[p.u] then floor = math.min(floor, F.petMult(p)) end end
    if floor == math.huge then return 0 end
    local cand = {}
    for _, p in ipairs(st.pets) do
        if not eq[p.u] and F.petMult(p) < floor then cand[#cand + 1] = p end
    end
    table.sort(cand, function(a, b) return F.petMult(a) < F.petMult(b) end)
    local need = all and #cand or (#st.pets - math.max(1, (tonumber(st.space) or 30) - 6))
    local del = {}
    for i = 1, math.min(need, #cand) do
        if cand[i].lk then M.fire("PetAction", "lock", cand[i].u) task.wait(0.15) end
        del[#del + 1] = cand[i].u
    end
    if #del > 0 then task.wait(0.4) M.fire("PetAction", "deletemany", del) S.deleted = (S.deleted or 0) + #del end
    return #del
end
function F.hatch()
    if os.clock() - F.petsFullAt < 45 then
        F.note = __T["Pets full"]
        if on("p_merge") then M.fire("PetAction", "mergeall") task.wait(0.5) end
        if on("p_free") then M.fire("PetAction", "sync") task.wait(1) if F.freeSpace() > 0 then F.petsFullAt = -1e9 F.note = "" end end
        if os.clock() - F.petsFullAt < 45 then return end
    end
    local i, e = F.eggChoice()
    if not i then F.note = __T["Can't afford an egg"] return end
    local keep = tonumber(val("p_keep", "0")) or 0
    if M.n("Wins") - keep < e.cost then F.note = __T["Saving wins"] return end
    local hub = Workspace.Map:FindFirstChild(M.world() == 2 and "Hub2" or "Hub")
    local m = hub and hub:FindFirstChild("Eggs") and hub.Eggs:FindFirstChild("Egg" .. i)
    if not m then return end
    F.note = ""
    S.task = __T["Hatching "] .. tostring(e.name)
    M.tp(m:GetPivot().Position + Vector3.new(0, 3, 5))
    task.wait(0.4)
    local n = 0
    while RUNNING and on("p_hatch") and M.n("Wins") - keep >= e.cost and n < 25 and os.clock() - F.petsFullAt > 2 do
        local luck = D.PL and gcall(D.PL.luckOfPlayer, lp, Workspace:GetServerTimeNow()) or 1
        local count = (M.n("Wins") - keep >= e.cost * 3) and 3 or 1
        local t0 = F.lastHatched
        M.fire("Hatch", i, count, nil, luck)
        local t = os.clock()
        repeat task.wait(0.05) until F.lastHatched ~= t0 or os.clock() - t > 2
        if F.lastHatched == t0 then
            if count == 3 then
                M.fire("Hatch", i, 1, nil, luck)
                t = os.clock()
                repeat task.wait(0.05) until F.lastHatched ~= t0 or os.clock() - t > 2
            end
            if F.lastHatched == t0 then break end
        end
        n += 1
    end
    if n > 0 then
        if on("p_merge") then M.fire("PetAction", "mergeall") task.wait(0.5) end
        if on("p_best") then M.fire("PetAction", "best") task.wait(0.5) end
        if on("p_free") then M.fire("PetAction", "sync") task.wait(1) F.freeSpace(true) end
    end
end
function F.raidWorld()
    if not RAID then return nil end
    local b = tostring(RAID:GetAttribute("Boss") or "")
    if RB and RB.worldOf then local w = gcall(RB.worldOf, b) return w == 2 and 2 or 1 end
    return 1
end
function F.inArena(centre)
    local root = M.root()
    if not (root and typeof(centre) == "Vector3") then return false end
    local reach = (tonumber(RAID:GetAttribute("Reach")) or 66) + 30
    local d = Vector3.new(root.Position.X - centre.X, 0, root.Position.Z - centre.Z).Magnitude
    return d <= reach
end
function F.raidSpot(centre)
    local rb = Workspace:FindFirstChild("RaidBoss")
    local core = rb and rb:FindFirstChild("Core")
    if not (core and typeof(centre) == "Vector3") then return nil end
    local reach = (tonumber(RAID:GetAttribute("Reach")) or 66) - 6
    local cp = core.Position
    local dir = F.flat(centre - cp)
    dir = dir.Magnitude > 0.1 and dir.Unit or Vector3.new(0, 0, 1)
    local spot = cp + dir * 12
    local off = F.flat(spot - centre)
    if off.Magnitude > reach then spot = Vector3.new(centre.X, spot.Y, centre.Z) + off.Unit * reach end
    return Vector3.new(spot.X, (M.root() and M.root().Position.Y) or spot.Y, spot.Z), cp
end
function F.raid()
    if not (RAID and RAID:GetAttribute("Active") == true) then return false end
    if F.raidSkip and F.raidSkip == RAID:GetAttribute("NextRaidAt") then return false end
    if F.raidWorld() ~= M.world() then return false end
    local centre = RAID:GetAttribute(M.world() == 2 and "Centre2" or "Centre")
    S.task = __T["Raid: "] .. tostring(RAID:GetAttribute("BossName") or __T["boss"])
    local iv = (tonumber(D.B.attackInterval) or 0.35) * 0.8
    local t = os.clock()
    local lastGo, tries = 0, 0
    F.hold = nil
    while RUNNING and on("f_raid") and RAID:GetAttribute("Active") == true and os.clock() - t < 300 do
        if not M.alive() then task.wait(1)
        elseif not F.inArena(centre) then
            F.hold = nil
            if os.clock() - lastGo > 4 then
                if tries >= 4 then F.raidSkip = RAID:GetAttribute("NextRaidAt") break end
                if M.a("InRun") then F.leave() task.wait(0.6) end
                lastGo = os.clock()
                tries += 1
                M.fire("Raid", "go")
            end
            task.wait(0.3)
        else
            local reach = (tonumber(RAID:GetAttribute("Reach")) or 66) - 4
            local dodged = on("f_dodge") and F.dodge(centre, reach)
            if not dodged then
                local spot = F.raidSpot(centre)
                local root = M.root()
                if spot and root and (not on("f_dodge") or F.safe(spot)) and F.flat(root.Position - spot).Magnitude > 8 then
                    F.hold = spot
                    M.tp(spot)
                elseif not F.hold and root then
                    F.hold = root.Position
                end
            end
            M.fire("Attack", { -1 })
            F.tech({ -1 })
            task.wait(iv)
        end
    end
    F.hold = nil
    F.zones = {}
    F.raids += 1
    return true
end
function F.eat()
    local gojo = M.a("GojoOn") == true
    local doms = (gojo and D.B.gojoDomains) or D.B.domains or {}
    local base = gojo and 100 or 0
    local n = 0
    for _ = 1, #doms do
        local owned = math.max(1, M.n("DomainsOwned"))
        local d = doms[owned + 1]
        if not d or d.product or d.paid then break end
        if M.n(gojo and "GojoWins" or "Wins") < (tonumber(d.need) or math.huge) then break end
        if (tonumber(d.stage) or 0) > M.n("BestStage") then break end
        M.fire("UnlockDomain", owned + 1)
        local t = os.clock()
        repeat task.wait(0.1) until M.n("DomainsOwned") > owned or os.clock() - t > 4
        if M.n("DomainsOwned") <= owned then break end
        n += 1
        S.eaten = (S.eaten or 0) + 1
        task.wait(0.3)
    end
    local own = M.n("DomainsOwned")
    if own > 0 and M.n("Domain") ~= base + own then M.fire("EquipDomain", own, false) end
    return n
end
function F.shop()
    local list = (M.world() == 2 and D.B.fingerShop2) or D.B.fingerShop or {}
    local tokens = M.n("Fingers")
    local pick
    for i, it in ipairs(list) do
        if it.kind == "flame" and not F.shopDone[M.world() .. ":" .. i] then
            if tokens >= (tonumber(it.price) or math.huge) then pick = i end
            break
        end
    end
    if not pick then
        local saving = false
        for i, it in ipairs(list) do if it.kind == "flame" and not F.shopDone[M.world() .. ":" .. i] then saving = true break end end
        for i, it in ipairs(list) do
            if it.kind == "boost" and M.n("BoostCE") < Workspace:GetServerTimeNow() + 60 and tokens >= (tonumber(it.price) or math.huge) * (saving and 3 or 1) then pick = i break end
        end
    end
    if not pick then return end
    local hub = Workspace.Map:FindFirstChild(M.world() == 2 and "Hub2" or "Hub")
    local fs = hub and hub:FindFirstChild("FingerShop")
    if not fs then return end
    S.task = __T["Token shop"]
    M.tp(fs:GetPivot().Position + Vector3.new(0, 4, 6))
    task.wait(0.6)
    local t0 = F.boughtAt
    M.fire("Raid", "buy", pick)
    local t = os.clock()
    repeat task.wait(0.1) until F.boughtAt ~= t0 or os.clock() - t > 2
    if F.boughtAt == t0 and list[pick].kind == "flame" then F.shopDone[M.world() .. ":" .. pick] = true end
    if F.boughtAt ~= t0 and list[pick].kind == "flame" then F.shopDone[M.world() .. ":" .. pick] = true end
end
function F.rebirth()
    if os.clock() - F.lastReb < 4 then return end
    local need = M.n("RebirthLevel")
    if need > 0 and M.n("Level") >= need then
        F.lastReb = os.clock()
        local r0 = M.n("Rebirths")
        M.fire("Rebirth")
        task.wait(1)
        if M.n("Rebirths") > r0 then S.rebirths += 1 F.fail = {} F.soft = {} F.stat = {} end
    end
end
task.spawn(function()
