                    F.fail[stg] = nil
                    local st = F.stat[stg] or { n = 0, t = 0 }
                    st.n += 1
                    st.t += (os.clock() - F.runT0)
                    if st.n > 6 then st.t = st.t / st.n * 6 st.n = 6 end
