        if #msg > 500 then setText(status, ERR.too_long); return end
        local low = msg:lower()
        if low:find("http", 1, true) or low:find("discord.gg", 1, true) or low:find("www.", 1, true) or low:find(".gg/", 1, true) then setText(status, ERR.no_links); return end
        setText(status, __T["Sending..."])
        task.spawn(function()
            local ok, err = send(tostring(val("FeedbackType", "Suggestion")):lower(), msg)
            if ok then last = tick(); setText(status, __T["Sent. Thank you!"]); pcall(function() Opt.FeedbackMsg:SetValue("") end)
